<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Http\Requests\Api\BatchProductionRequest;use App\Http\Resources\BatchProductionResource;use App\Models\BatchProduction;use App\Repositories\BatchProductionRepository;use App\Services\CrudService;
class BatchProductionController extends Controller{private CrudService $service;public function __construct(BatchProductionRepository $r){$this->service=new CrudService($r);}public function index(){return BatchProductionResource::collection($this->service->all(['machine.controllers.devices','recipe.steps','operator']));}public function store(BatchProductionRequest $r){$data=$r->validated()+['operator_id'=>$r->input('operator_id',$r->user()->id)];return (new BatchProductionResource($this->service->create($data)->load('machine','recipe.steps','operator')))->response()->setStatusCode(201);}public function show(BatchProduction $batch){return new BatchProductionResource($batch->load('machine.controllers.devices','recipe.steps','operator'));}public function update(BatchProductionRequest $r,BatchProduction $batch){return new BatchProductionResource($this->service->update($batch,$r->validated())->load('machine','recipe.steps','operator'));}public function destroy(BatchProduction $batch){$this->service->delete($batch);return response()->noContent();}}
